  2365  M3Result  Compile_Function  (IM3Function io_function)
  2366  {
  2367      IM3FuncType funcType = io_function->funcType;
  2368
  2369      M3Result result = m3Err_none;                                   m3log (compile, "compiling: '%s'; wasm-size: %d; numArgs: %d; return: %s",
  2370                                                                             m3_GetFunctionName(io_function), (u32) (io_function->wasmEnd - io_function->wasm), GetFunctionNumArgs (io_function),
  2371                                                                             c_waTypes [GetSingleRetType(funcType)]);
  2372      IM3Runtime runtime = io_function->module->runtime;
  2373
  2374      IM3Compilation o = & runtime->compilation;                      d_m3Assert (d_m3MaxFunctionSlots >= d_m3MaxFunctionStackHeight * (d_m3Use32BitSlots + 1))  // need twice as many slots in 32-bit mode
  2375      SetupCompilation (o);
  2376
  2377      o->runtime  = runtime;
  2378      o->module   = io_function->module;
  2379      o->function = io_function;
  2380      o->wasm     = io_function->wasm;
  2381      o->wasmEnd  = io_function->wasmEnd;
  2382      o->block.type = funcType;
  2383
  2384  _try {
  2385      // skip over code size. the end was already calculated during parse phase
  2386      u32 size;
  2387  _   (ReadLEB_u32 (& size, & o->wasm, o->wasmEnd));                  d_m3Assert (size == (o->wasmEnd - o->wasm))
  2388
  2389  _   (AcquireCompilationCodePage (o, & o->page));
  2390
  2391      pc_t pc = GetPagePC (o->page);
  2392
  2393      // all args & returns are 64-bit aligned, so use 2 slots for a d_m3Use32BitSlots=1 build
  2394      const u32 ioSlotCount = sizeof (u64) / sizeof (m3slot_t);
  2395
  2396      u32 numRetSlots = GetFunctionNumReturns (o->function) * ioSlotCount;
  2397
  2398      for (u32 i = 0; i < numRetSlots; ++i)
  2399          MarkSlotAllocated (o, i);
  2400
  2401      o->function->numRetSlots = o->firstDynamicSlotIndex = numRetSlots;
  2402
  2403      u32 numArgs = GetFunctionNumArgs (o->function);
  2404
  2405      // push the arg types to the type stack
  2406      for (u32 i = 0; i < numArgs; ++i)
  2407      {
  2408          u8 type = GetFunctionArgType (o->function, i);
  2409  _       (PushAllocatedSlot (o, type));
  2410
  2411          // prevent allocator fill-in
  2412          o->firstDynamicSlotIndex += ioSlotCount;
  2413      }
  2414
  2415      o->maxAllocatedSlotPlusOne = o->function->numRetAndArgSlots = o->firstLocalSlotIndex = o->firstDynamicSlotIndex;
  2416
  2417  _   (CompileLocals (o));
  2418
  2419      u16 maxSlot = GetMaxUsedSlotPlusOne (o);
  2420
  2421      o->function->numLocalBytes = (maxSlot - o->firstLocalSlotIndex) * sizeof (m3slot_t);
  2422
  2423      o->firstConstSlotIndex = o->maxConstSlotIndex = maxSlot;
  2424
  2425      // ReserveConstants initializes o->firstDynamicSlotIndex
  2426  _   (Compile_ReserveConstants (o));
  2427
  2428      // start tracking the max stack used (Push() also updates this value) so that op_Entry can precisely detect stack overflow
  2429      o->function->maxStackSlots = o->maxAllocatedSlotPlusOne = o->firstDynamicSlotIndex;
  2430
  2431      o->block.initStackIndex = o->firstDynamicStackIndex = o->stackIndex;                           m3log (compile, "start stack index: %d", (u32) o->firstDynamicStackIndex);
  2432
  2433  _   (EmitOp (o, op_Entry));
  2434      EmitPointer (o, io_function);
  2435
  2436  _   (Compile_BlockStatements (o));
  2437
  2438      io_function->compiled = pc;
  2439
  2440      u32 numConstantSlots = o->maxConstSlotIndex - o->firstConstSlotIndex;       m3log (compile, "unique constant slots: %d; unused slots: %d", numConstantSlots, o->firstDynamicSlotIndex - o->maxConstSlotIndex);
  2441
  2442      io_function->numConstantBytes = numConstantSlots * sizeof (m3slot_t);
  2443
  2444      if (numConstantSlots)
  2445      {
  2446          io_function->constants = m3_CopyMem (o->constants, io_function->numConstantBytes);
  2447          _throwifnull(io_function->constants);
  2448      }
  2449
  2450  } _catch:
  2451
  2452      ReleaseCompilationCodePage (o);
  2453
  2454      return result;
  2455  }
