   550  M3Result  m3_ParseModule  (IM3Environment i_environment, IM3Module * o_module, cbytes_t i_bytes, u32 i_numBytes)
   551  {
   552      M3Result result;
   553
   554      IM3Module module;
   555  _try {
   556      module = m3_AllocStruct (M3Module);
   557      _throwifnull(module);
   558      module->name = ".unnamed";                                                      m3log (parse, "load module: %d bytes", i_numBytes);
   559      module->startFunction = -1;
   560      //module->hasWasmCodeCopy = false;
   561      module->environment = i_environment;
   562
   563      const u8 * pos = i_bytes;
   564      const u8 * end = pos + i_numBytes;
   565
   566      module->wasmStart = pos;
   567      module->wasmEnd = end;
   568
   569      u32 magic, version;
   570  _   (Read_u32 (& magic, & pos, end));
   571  _   (Read_u32 (& version, & pos, end));
   572
   573      _throwif (m3Err_wasmMalformed, magic != 0x6d736100);
   574      _throwif (m3Err_incompatibleWasmVersion, version != 1);
   575                                                                                      m3log (parse,  "found magic + version");
   576      u8 previousSection = 0;
   577
   578      while (pos < end)
   579      {
   580          u8 section;
   581  _       (ReadLEB_u7 (& section, & pos, end));
   582
   583          if (section > previousSection or                    // from the spec: sections must appear in order
   584              section == 0 or                                 // custom section
   585              (section == 12 and previousSection == 9) or     // if present, DataCount goes after Element
   586              (section == 10 and previousSection == 12))      // and before Code
   587          {
   588              u32 sectionLength;
   589  _           (ReadLEB_u32 (& sectionLength, & pos, end));
   590              _throwif(m3Err_wasmMalformed, pos + sectionLength > end);
   591  _           (ParseModuleSection (module, section, pos, sectionLength));
   592
   593              pos += sectionLength;
   594
   595              if (section)
   596                  previousSection = section;
   597          }
   598          else _throw (m3Err_misorderedWasmSection);
   599      }
   600
   601      } _catch:
   602
   603      if (result)
   604      {
   605          m3_FreeModule (module);
   606          module = NULL;
   607      }
   608
   609      * o_module = module;
   610
   611      return result;
   612  }
